(function (global) {
'use strict';
var HttpApi = global.HttpApi;
var signCache = null;
function ensureSignature() {
if (signCache && signCache.host && signCache.expire * 1000 - 30000 > Date.now()) {
return Promise.resolve(signCache);
}
return HttpApi.merchant.uploadSign({}).then(function (res) {
var sign = (res && res.data) || res;
if (!res || res.code !== 0 || !sign || !sign.host) {
throw new Error((res && res.msg) || '获取上传签名失败');
}
signCache = sign;
return sign;
});
}
function extOf(file) {
var name = String((file && file.name) || '');
var dot = name.lastIndexOf('.');
return dot > -1 ? name.slice(dot).toLowerCase() : '';
}
function buildKey(dir, file, extHint) {
var ext = extOf(file) || (extHint ? '.' + String(extHint).replace(/^\./, '') : '');
var base = dir && dir.charAt(dir.length - 1) === '/' ? dir : String(dir || '') + '/';
var rand = Math.random().toString(36).slice(2, 8);
return base + Date.now() + '_' + rand + ext;
}
function hostOf(sign) {
return String(sign.host || '').replace(/\/+$/, '');
}
function uploadFile(file, extHint) {
if (!file) return Promise.reject(new Error('未选择文件'));
return ensureSignature().then(function (sign) {
var key = buildKey(sign.dir, file, extHint);
var form = new FormData();
form.append('key', key);
form.append('policy', sign.policy);
form.append('OSSAccessKeyId', sign.accessid);
form.append('signature', sign.signature);
form.append('success_action_status', '200');
form.append('file', file);
return fetch(sign.host, { method: 'POST', body: form }).then(function (res) {
if (res.ok || res.status === 204) return hostOf(sign) + '/' + key;
return res.text().then(function (text) {
throw new Error('上传失败(' + res.status + ')' + (text ? '：' + text.slice(0, 80) : ''));
});
}).catch(function (err) {
if (err && /上传失败/.test(err.message || '')) throw err;
throw new Error('上传失败，请检查网络或存储跨域配置');
});
});
}
function pickFile(accept) {
return new Promise(function (resolve, reject) {
var input = document.createElement('input');
input.type = 'file';
if (accept) input.accept = accept;
input.style.display = 'none';
document.body.appendChild(input);
var settled = false;
var timer = null;
function cleanup() {
if (timer) clearTimeout(timer);
global.removeEventListener('focus', onFocus);
if (input.parentNode) input.parentNode.removeChild(input);
}
function finish(fn, payload) {
if (settled) return;
settled = true;
cleanup();
fn(payload);
}
function onFocus() {
timer = setTimeout(function () {
if (!input.files || !input.files.length) finish(reject, new Error('cancel'));
}, 400);
}
input.addEventListener('change', function () {
var file = input.files && input.files[0];
if (file) finish(resolve, file);
else finish(reject, new Error('cancel'));
});
global.addEventListener('focus', onFocus);
input.click();
});
}
function uploadImage() {
return pickFile('image/*').then(function (file) {
return uploadFile(file, 'jpg');
});
}
function readVideoDuration(file) {
return new Promise(function (resolve) {
var url = URL.createObjectURL(file);
var video = document.createElement('video');
video.preload = 'metadata';
var done = function (value) {
URL.revokeObjectURL(url);
resolve(value);
};
video.onloadedmetadata = function () {
var d = Number(video.duration);
done(isFinite(d) ? Math.round(d) : 0);
};
video.onerror = function () { done(0); };
video.src = url;
});
}
function uploadVideo() {
return pickFile('video/*').then(function (file) {
return Promise.all([uploadFile(file, 'mp4'), readVideoDuration(file)]).then(function (out) {
return { url: out[0], duration: out[1] };
});
});
}
global.MerchantUpload = {
uploadFile: uploadFile,
uploadImage: uploadImage,
uploadVideo: uploadVideo
};
})(window);
